namespace Quantum.Cryptography {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;

    // BB84 state preparation
    operation PrepareBB84State(bit : Bool, basis : Bool, q : Qubit) : Unit {
        // basis: false = rectilinear (Z), true = diagonal (X)
        // bit: false = 0/+, true = 1/-

        if (bit) {
            X(q);  // |1⟩ or |-⟩ component
        }

        if (basis) {
            H(q);  // Switch to X basis for |+⟩/|-⟩
        }
    }

    // BB84 measurement
    operation MeasureBB84(basis : Bool, q : Qubit) : Bool {
        if (basis) {
            H(q);  // Rotate from X to Z basis
        }
        return ResultAsBool(M(q));
    }

    @EntryPoint()
    operation BB84Demo() : (Int, Int) {
        use q = Qubit();

        mutable matches = 0;
        mutable errors = 0;

        for (i in 0..99) {
            // Alice's random choices
            let aliceBit = (i % 2) == 0;  // Simplified: alternating bits
            let aliceBasis = (i % 3) != 0;  // Mix of bases

            // Prepare state
            PrepareBB84State(aliceBit, aliceBasis, q);

            // Bob's random measurement basis
            let bobBasis = (i % 4) < 2;
            let bobResult = MeasureBB84(bobBasis, q);

            // Check if bases match
            if (aliceBasis == bobBasis) {
                set matches += 1;
                if (aliceBit != bobResult) {
                    set errors += 1;
                }
            }

            Reset(q);
        }

        Message($"Sifted bits: {matches}, Errors: {errors}");
        return (matches, errors);
    }
}
